-- Migration 058: correzioni a due articoli News.
-- 1) spese-notarili-accessorie: la stima "7-12% del prezzo" vale con un'agenzia; senza,
--    una prima casa da privato si ferma intorno al 4% (imposte sul valore catastale).
--    Frase corretta e nuova tabella di calcolo (build/news/visuals_mutui.py, spese_table).
-- 2) tracciare-spese: tabella solo testo semplificata, celle allineate in alto.

UPDATE news_articles SET body = REPLACE(REPLACE(body,
    '<figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Le spese accessorie in sintesi</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Voce</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Da cosa dipende</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Notaio (compravendita e mutuo)</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Valore dell''immobile e notaio scelto: onorari negoziabili</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Imposte di registro, ipotecaria e catastale</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Prima o seconda casa, acquisto da privato o da impresa (IVA)</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Imposta sostitutiva sul mutuo</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Importo finanziato, aliquota agevolata per la prima casa</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Perizia e istruttoria</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Banca: costo fisso o in percentuale, a volte azzerato in promozione</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Agenzia immobiliare</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Percentuale sul prezzo, da contrattare prima</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Chiedi un preventivo scritto al notaio e il dettaglio delle spese alla banca prima di firmare il preliminare.</p></figure>',
    '<figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Le spese accessorie in sintesi</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Voce</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Da cosa dipende</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Notaio (compravendita e mutuo)</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Valore dell''immobile e notaio scelto: onorari negoziabili</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Imposte di registro, ipotecaria e catastale</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Prima o seconda casa, acquisto da privato o da impresa (IVA)</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Imposta sostitutiva sul mutuo</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Importo finanziato, aliquota agevolata per la prima casa</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Perizia e istruttoria</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Banca: costo fisso o in percentuale, a volte azzerato in promozione</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Agenzia immobiliare</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Percentuale sul prezzo, da contrattare prima</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Chiedi un preventivo scritto al notaio e il dettaglio delle spese alla banca prima di firmare il preliminare.</p></figure>'),
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Come ordine di grandezza indicativo, le spese accessorie complessive (notaio, imposte, perizia, istruttoria, eventuale agenzia) si aggirano spesso tra il 7% e il 12% del prezzo dell''immobile, con forti variazioni in base a prima/seconda casa, provenienza da privato o costruttore, e città. Vale sempre la pena farsi fare un preventivo scritto dal notaio prima del rogito, non dopo.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Come ordine di grandezza indicativo, le spese accessorie complessive (notaio, imposte, perizia, istruttoria, eventuale agenzia) si aggirano spesso tra il 7% e il 12% del prezzo dell''immobile quando c''è di mezzo un''agenzia, e possono scendere intorno al 4% per una prima casa comprata da un privato senza intermediari, con forti variazioni in base a prima/seconda casa, provenienza da privato o costruttore, e città. Vale sempre la pena farsi fare un preventivo scritto dal notaio prima del rogito, non dopo.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Esempio: casa da 200.000 euro con mutuo da 160.000 (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5"></th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Prima casa da privato</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Seconda casa da privato</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Prima casa da impresa</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Imposte sull''acquisto</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.717</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">8.038</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">8.600</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Notaio, due atti</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">4.300</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">4.300</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">4.300</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Imposta sul mutuo</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">400</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">3.200</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">400</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Perizia e istruttoria</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.100</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.100</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1.100</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Totale senza agenzia</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">7.517</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">16.638</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">14.400</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">in % del prezzo</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">3,8%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">8,3%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">7,2%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Con agenzia (3% + IVA)</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">14.837</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">23.958</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">21.720</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">in % del prezzo</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">7,4%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">12,0%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">10,9%</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Stima indicativa. Da privato le imposte si pagano sul valore catastale (qui con una rendita di 700 euro), non sul prezzo: per questo la prima casa costa molto meno. Da impresa si paga l''IVA sul prezzo (4% prima casa). Notaio: atto di compravendita e atto di mutuo. Notaio, perizia e istruttoria variano: chiedi sempre i preventivi.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'spese-notarili-accessorie-mutuo-costo-reale-acquisto-casa' AND body LIKE '%si aggirano spesso tra il 7% e il 12% del prezzo dell''immobile, con forti variazioni%';

UPDATE news_articles SET body = REPLACE(body,
    '<figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Inserimento manuale o collegamento automatico</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5"></th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">A mano</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Collegamento bancario</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Tempo richiesto</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Pochi secondi a spesa</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Quasi nullo</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Consapevolezza</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Alta: ogni spesa è una scelta</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Bassa: le spese scorrono in un elenco</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Accesso ai dati</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Nessuno oltre a te</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Un servizio terzo vede ogni movimento</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Completezza</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Dipende dalla costanza</td><td class="px-3 py-2 sm:px-4 sm:py-2.5">Tutto il conto, in automatico</td></tr></tbody></table></div></figure>',
    '<figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Inserimento manuale o collegamento automatico</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5"></th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">A mano</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Collegamento</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Tempo</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Secondi per spesa</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Quasi zero</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Consapevolezza</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Alta</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Bassa</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Chi vede i dati</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Solo tu</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Anche un servizio terzo</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Completezza</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Dipende da te</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 align-top">Automatica</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Collegamento: accesso al conto tramite open banking (PSD2). Inserire a mano ogni spesa trasforma un pagamento in una scelta consapevole.</p></figure>')
WHERE slug = 'tracciare-spese-manualmente-vs-collegamento-bancario' AND body LIKE '%Pochi secondi a spesa%';
